                    }
                }
            }
            .padding(.horizontal, 2)
        }
        .frame(height: 32)
    }

    // MARK: - Actions

    private func send(withEnter: Bool) {
        let text = draft
        guard !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
